export const concepts: ConceptQuestion[] = rows.map((r, i) => {
  const [t, level, slug, title, minutes, question, right, wrong, why, sayIt, followUp, trap, sceneId] = r
  const answer = (i * 3 + 1) % 4 // cycles 1, 0, 3, 2 so the right answer moves around
  const options = [...wrong]
  options.splice(answer, 0, right)
  const q: ConceptQuestion = { id: `sql-c-${slug}`, topic: conceptTopics[t], level, title, minutes, question, options, answer, why, sayIt, followUp, trap }
  if (sceneId) q.sceneId = sceneId
  return q
})
